function decode(value:any):any{if(typeof value==='string'&&/^[\[{]/.test(value.trim())){try{return JSON.parse(value)}catch{}}return value}
const hidden=new Set(['tenantId','deleted','requestId','previewToken','fingerprint','checksum','audioSha','inputJson','snapshotJson','draftJson','extractionJson'])
const items=computed(()=>{const v=decode(props.value);const entries=Array.isArray(v)?v.map((x:any,i:number)=>[String(i),x]):v&&typeof v==='object'?Object.entries(v):[['value',v]];return entries.filter(([k,v]:any)=>v!==null&&v!==undefined&&!hidden.has(k)).map(([key,value]:any)=>({key,label:Array.isArray(v)?`第 ${Number(key)+1} 项`:(labels[key] || (key==='value'?'内容':/[a-zA-Z]/.test(key)?'补充信息':key)),value:decode(value),nested:typeof decode(value)==='object'}))})
const toggle=(key:string)=>expanded.value[key]=!expanded.value[key]
function display(value:any):string {if(typeof value==='boolean')return value?'是':'否';return statusLabels[String(value)] || String(value ?? '—')}
